class Producto:
    def __init__(self, nombre, precio):
        self.nombre = nombre
        self.precio = precio

    def __repr__(self):
        return f"Producto({self.nombre!r}, {self.precio})"

    def __str__(self):
        return f"{self.nombre}: S/ {self.precio:.2f}"

    def __eq__(self, otro):
        if not isinstance(otro, Producto):
            return NotImplemented
        return (self.nombre, self.precio) == (otro.nombre, otro.precio)

    @property
    def precio_con_igv(self):
        return round(self.precio * 1.18, 2)

    @classmethod
    def desde_texto(cls, linea):
        nombre, precio = linea.rsplit(",", 1)
        return cls(nombre, float(precio))

    @staticmethod
    def es_precio_valido(valor):
        return valor > 0

p = Producto.desde_texto("Laptop,2500")
