#include <iostream>
#include <stdexcept>

class Temperatura {
public:
    explicit Temperatura(double celsius) : celsius_(celsius) {}

    double celsius() const { return celsius_; }

    void set_celsius(double valor) {
        if (valor < -273.15) {
            throw std::invalid_argument("por debajo del cero absoluto");
        }
        celsius_ = valor;
    }

    bool operator==(const Temperatura& otra) const {
        return celsius_ == otra.celsius_;
    }

    friend std::ostream& operator<<(std::ostream& os, const Temperatura& t) {
        return os << t.celsius_ << " C";
    }

private:
    double celsius_;
};

int main() {
    Temperatura t{20.0};
    t.set_celsius(25.0);
    std::cout << t << '\n';
    std::cout << std::boolalpha << (t == Temperatura{25.0}) << '\n';
    return 0;
}

