class CuentaBancaria:
    def __init__(self, titular, saldo=0):
        self.titular = titular
        self.saldo = saldo

    @property
    def saldo(self):
        return self._saldo

    @saldo.setter
    def saldo(self, valor):
        if valor < 0:
            raise ValueError("el saldo no puede ser negativo")
        self._saldo = valor

    def depositar(self, monto):
        if monto <= 0:
            raise ValueError("el monto debe ser positivo")
        self.saldo += monto

    def retirar(self, monto):
        if monto > self.saldo:
            raise ValueError("saldo insuficiente")
        self.saldo -= monto

    def __repr__(self):
        return f"CuentaBancaria({self.titular!r}, {self.saldo})"

c = CuentaBancaria("Ana", 100)
c.depositar(50)
c.retirar(30)
print(c)
try:
    c.saldo = -1
except ValueError as error:
    print("ValueError:", error)

class Inventario:
    def __init__(self, unidades=None):
        self.unidades = dict(unidades or {})

    def __len__(self):
        return sum(self.unidades.values())

    def __add__(self, otro):
        combinado = dict(self.unidades)
        for producto, cantidad in otro.unidades.items():
            combinado[producto] = combinado.get(producto, 0) + cantidad
        return Inventario(combinado)

    def __eq__(self, otro):
        if not isinstance(otro, Inventario):
            return NotImplemented
        return self.unidades == otro.unidades

    def __repr__(self):
        return f"Inventario({self.unidades!r})"

    @classmethod
    def desde_lineas(cls, lineas):
        unidades = {}
        for linea in lineas:
            producto, cantidad = linea.split(",")
            unidades[producto] = int(cantidad)
        return cls(unidades)

    @staticmethod
    def es_cantidad_valida(cantidad):
        return isinstance(cantidad, int) and cantidad >= 0

i1 = Inventario.desde_lineas(["pan,3", "leche,2"])
i2 = Inventario({"pan": 1, "café": 4})
print(i1 + i2)
print(len(i1 + i2))
print(Inventario.es_cantidad_valida(-2))

